const { refreshManagedSubscriptions } = require('./managed-native-bridge')

function createSubscriptionRecovery ({ panelId, flowAccess, onError = () => {}, delayMs = 1000 }) {
  const streams = new Map(), repaired = new Map(), timers = new Map()
  let closed = false, pending = Promise.resolve()
  const key = message => JSON.stringify([message.device, message.streamId])
  function payload (message) {
    try {
      let value = message.payload?.data ?? message.payload
      if (typeof value === 'string') value = JSON.parse(value)
      return value
    } catch (_) { return null }
  }
  return {
    accepted (message) {
      const data = payload(message)
      if (closed || !flowAccess || !data?.epoch || typeof data.epoch !== 'string') return
      const id = key(message)
      if (message.kind.endsWith('-frame')) {
        if (streams.get(id)?.epoch === data.epoch) {
          streams.get(id).fresh = true
          clearTimeout(timers.get(id)); timers.delete(id)
        }
        return
      }
      const previous = streams.get(id)
      const current = previous?.epoch === data.epoch ? previous
        : { epoch: data.epoch, replaced: Boolean(previous), fresh: false }
      streams.set(id, current)
      if (!current.replaced || current.fresh || repaired.get(message.device) === data.epoch || timers.has(id)) return
      const timer = setTimeout(() => {
        timers.delete(id)
        pending = pending.then(async () => {
          if (closed || streams.get(id) !== current || current.fresh || repaired.get(message.device) === data.epoch) return
          const snapshot = await flowAccess.getSnapshot()
          if (closed || streams.get(id) !== current || current.fresh) return
          const flows = refreshManagedSubscriptions(snapshot.flows,
            { panelId, device: message.device, epoch: data.epoch })
          if (!flows) return
          await flowAccess.setSnapshot({ rev: snapshot.rev, flows })
          repaired.set(message.device, data.epoch)
        }).catch(onError)
      }, delayMs)
      timer.unref?.()
      timers.set(id, timer)
    },
    close () { closed = true; for (const timer of timers.values()) clearTimeout(timer); timers.clear() }
  }
}

module.exports = { createSubscriptionRecovery }
